from sources import cite


def introduction():
    blocks = []
    P = lambda text: blocks.append(("p", text))
    blocks.append(("h1", "ВВЕДЕНИЕ"))
    P("Защита детей остается обязанностью государства, а не разовой кампанией. Семья по закону стоит впереди учреждения, и большая часть детей, оставшихся без попечения родителей, сегодня действительно живет в семьях. При этом десятки тысяч детей по-прежнему воспитываются в организациях. Для них качество работы специалиста по социальной работе — это не отвлеченный вопрос кадров. От нее зависит, вернется ли ребенок домой, найдет ли новых взрослых и выйдет ли во взрослую жизнь с документами, жильем и умением обслужить себя.")
    P("Работа специалиста давно вышла за пределы выдачи одежды и контроля режима. Ребенку, который рос без устойчивого взрослого, нужно восстановить доверие, собрать прошлое, назвать ближайшее будущее и научиться обычным делам. Индивидуальный план развития и жизнеустройства, который организация составляет и который утверждает опека, как раз и должен держать эти задачи в одном документе. Пока план пишут общими словами, он не помогает ни ребенку, ни тому, кто через полгода будет проверять результат. Пока службы не передают друг другу сведения, ребенок живет между папками.")
    P("Тема разобрана в нескольких научных традициях, и они не заменяют одна другую. Е. И. Холостова, П. Д. Павленок, М. В. Фирсов и А. М. Панов описывают социальную работу как помощь человеку в трудной жизненной ситуации и как отдельную профессию со своим методом. Л. В. Мардахаев, А. В. Мудрик, М. А. Галагузова и Ф. А. Мустаева показывают педагогическую сторону той же помощи: воспитание идет в реальной среде, а не только на занятии. В. С. Мухина, И. В. Дубровина, А. Г. Рузская, А. М. Прихожан, Н. Н. Толстых и Л. М. Шипицына исследовали, как развивается ребенок вне семьи. И. Ф. Дементьева, Л. Я. Олиференко и Т. И. Шульга связывают сиротство с семейным неблагополучием и с ранней поддержкой, а не только с устройством уже изъятого ребенка. Правовую сторону держат Семейный кодекс, законы о гарантиях и об опеке, комментарии М. В. Антокольской, А. М. Нечаевой, Л. М. Пчелинцевой и Л. Ю. Михеевой.")
    P("Меньше проговорено то, что специалист делает по шагам, когда ребенок уже в организации Орловской области: как за месяц собрать картину, как не разлучить братьев, как не пропустить жилищный учет и как написать план, который через полгода можно проверить. Работы В. Н. Ослон, Н. П. Ивановой и Г. В. Семьи близки к этой практике, но региональную сводку и бланк плана они не заменяют. Отсюда цель и предмет данной работы.")
    P("Объект исследования — система социальной защиты детей-сирот и детей, оставшихся без попечения родителей. Предмет исследования — содержание, формы и методы профессиональной деятельности специалиста по социальной работе по жизнеустройству и сопровождению этих детей.")
    P("Цель работы — проанализировать организацию деятельности специалиста по социальной работе с детьми-сиротами и детьми, оставшимися без попечения родителей и разработать дорожную карту и индивидуальный план развития, которые помогают вести случай конкретного ребенка.")
    P("Для этого нужно решить четыре задачи. Рассмотреть детей-сирот и детей, оставшихся без попечения родителей как объект социальной работы и нормативное регулирование защиты детства. Описать профессиональный портрет и функции специалиста. Проанализировать современное состояние жизнеустройства таких детей в Орловской области и опыт службы по устройству в семью. Разработать дорожную карту ведения случая и учебный пример индивидуального плана развития и жизнеустройства.")
    P("Методы выбраны под эти задачи. Нормативные акты и научная литература дают язык и границы. Официальные сведения Министерства и Правительства России, доклад уполномоченного по правам ребенка в Орловской области, сообщения Правительства области и департамента социальной защиты дают цифры. Сопоставление нужно для того, чтобы не сложить в одну сумму данные разных лет. Обобщение собирает из норм и цифр порядок действий специалиста. Таблицы и рисунки удерживают этот порядок в обозримом виде. Опрос работников и изучение личных дел детей не проводились: для этого нужно отдельное согласие организации и защита тайны, а работа опирается на открытые документы.")
    P("База практических сведений — Орловская область. Это жилищный учет, пять центров помощи, школы приемных родителей, переподготовка опекунов и публичные отчеты за 2024–2026 годы. Общероссийские цифры нужны как рамка, чтобы областные успехи и областные очереди было с чем сравнить. " + cite("r1217", "По итогам 2024 года общая численность детей-сирот, находящихся на воспитании в семьях, составила 307,2 тысячи детей.") + " Рядом с этой величиной в том же документе указаны дети, которые еще живут в организациях. Во второй главе обе цифры разобраны вместе, чтобы доля семейного устройства не превращалась в лозунг.")
    P("Работа состоит из введения, двух глав, заключения и списка источников. Первая глава отвечает на вопрос, кто такой ребенок данной категории и кто такой специалист. Вторая глава отвечает на вопрос, что видно по стране и по Орловской области и как из этого собрать дорожную карту и план на одного воспитанника. В конце каждой главы выводы собраны отдельно, чтобы не искать их по всему тексту.")
    return blocks
